<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
var VBW = 680, VBH = 300;
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var margin = {left:62, right:24, top:18, bottom:46};
var PW = VBW - margin.left - margin.right;
var PH = VBH - margin.top - margin.bottom;
var labels = ["2/9","3/9","4/9","8/9","9/9","10/9","11/9","14/9","15/9","16/9","17/9","18/9","21/9","22/9","23/9","24/9","25/9","28/9","29/9","30/9","1/10"];
var vals = [15.20,14.32,14.53,15.72,16.46,17.84,15.84,17.10,17.20,17.71,15.44,14.81,14.87,14.21,15.18,15.67,14.87,16.07,16.04,16.34,16.39];
var n = vals.length;
var refVal = 21.8;
var evIdx = 17;
var lo = Math.min.apply(null, vals) - 1;
var hi = Math.max(Math.max.apply(null, vals), refVal) + 1;
function xp(i){ return margin.left + (i/(n-1))*PW; }
function yp(v){ return margin.top + ((hi - v)/(hi - lo))*PH; }
var ticks = [];
for (var t = Math.ceil(lo/2)*2; t <= hi; t += 2){ if (Math.abs(t - refVal) >= 0.5) ticks.push(t); }
var currentVal = vals[n-1];
var refY = yp(refVal);
var lastX = xp(n-1), lastY = yp(currentVal);
var evX = xp(evIdx);
ticks.forEach(function(tv){
  svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:yp(tv), y2:yp(tv), stroke:"#ececec", "stroke-width":"0.5"}));
});
svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:refY, y2:refY, stroke:"#2e7d32", "stroke-width":"1", "stroke-dasharray":"3,3"}));
var d = "";
vals.forEach(function(v,i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(v).toFixed(1) + " "; });
svg.appendChild(el("path",{d:d, fill:"none", stroke:"#4a5568", "stroke-width":"1.8", "stroke-linejoin":"round"}));
svg.appendChild(el("line",{x1:margin.left, x2:margin.left, y1:margin.top, y2:margin.top+PH, stroke:"#d8d8d8", "stroke-width":"1"}));
svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:margin.top+PH, y2:margin.top+PH, stroke:"#d8d8d8", "stroke-width":"1"}));
svg.appendChild(el("line",{x1:evX, x2:evX, y1:margin.top, y2:margin.top+PH, stroke:"#1a3560", "stroke-opacity":"0.5", "stroke-width":"1", "stroke-dasharray":"2,3"}));
vals.forEach(function(v,i){
  if (i === n-1) return;
  svg.appendChild(el("circle",{cx:xp(i), cy:yp(v), r:"2.5", fill:"#4a5568"}));
});
svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:"4", fill:"#4a5568"}));
var pillText = currentVal.toFixed(2).replace(".", ",");
var pillW = Math.ceil(pillText.length*9*0.58)+10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH - 10;
if (pillX < margin.left) pillX = margin.left;
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:"3", fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+3, "text-anchor":"middle", "font-size":"9", "font-weight":"700", fill:"#111111", "font-family":FONT}, pillText));
ticks.forEach(function(tv){
  svg.appendChild(el("text",{x:margin.left-6, y:yp(tv)+3, "text-anchor":"end", "font-size":"8.5", fill:"#aaaaaa", "font-family":FONT}, String(tv)));
});
labels.forEach(function(lb,i){
  svg.appendChild(el("text",{x:xp(i), y:margin.top+PH+14, "text-anchor":"middle", "font-size":"8", fill:"#999999", "font-family":FONT}, lb));
});
if (Math.abs(refVal - currentVal)/currentVal >= 0.03){
  svg.appendChild(el("text",{x:margin.left+10, y:refY-10, "text-anchor":"start", "font-size":"7", "font-weight":"700", fill:"#2e7d32", "font-family":FONT}, "MOYENNE D’OCT. 25 ANS 21,8"));
}
var evPct = ((vals[evIdx]/vals[evIdx-1]) - 1)*100;
var evLines = ["28/9", "+" + evPct.toFixed(1).replace(".", ",") + "\u00a0% SÉANCE"];
var evW = 0;
evLines.forEach(function(s){ evW = Math.max(evW, Math.ceil(s.length*7*0.68)); });
var nearRight = (evX + evW + 3) > (margin.left + PW);
var evAnchor = nearRight ? "end" : "start";
var evOff = nearRight ? -3 : 3;
evLines.forEach(function(s,k){
  svg.appendChild(el("text",{x:evX+evOff, y:refY+14+k*10, "text-anchor":evAnchor, "font-size":"7", "font-weight":"700", fill:"#1a3560", "font-family":FONT}, s));
});
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: clôtures quotidiennes de l’indice de volatilité Cboe, Investing.com, du 2 septembre au 1er octobre 2026, exclusion faite du congé boursier américain du 7 septembre&nbsp;; moyenne d’octobre d’environ 21,8 tirée de l’analyse de Stan Wong sur des données de Bloomberg, BNN Bloomberg, 1er octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">La ligne de référence de 21,8 est une moyenne des clôtures quotidiennes de 25 mois d’octobre, de 2001 à 2025, et comprend des années de crise comme 2008. La hausse du 28 septembre est survenue alors que le rendement des bons du Trésor à 10 ans dépassait 5,2&nbsp;% après que le président Donald Trump a rejeté les conditions de cessez-le-feu énoncées par l’Iran, selon Qz.</p>
<p>La tension se trouve sur cet autre marché. Le rendement des bons du Trésor à 10 ans a atteint 5,342&nbsp;% le 1er octobre, son plus haut niveau depuis 2002, après la plus forte hausse trimestrielle des rendements de ce siècle, selon Reuters. Il a clôturé à 5,243&nbsp;%, selon CNBC. Le rendement canadien à 10 ans a atteint 3,99&nbsp;% en début de séance, près de son plus haut depuis 2023.</p>
<p>Reuters attribue la hausse mondiale des rendements à la flambée des coûts de l’énergie, qui alimente l’inflation, et à l’essor de la construction de centres de données pour l’IA, qui relève les attentes de croissance et de niveau de stabilisation des taux à court terme. L’indice composé S&amp;P/TSX a clôturé à 35&nbsp;154,76 le 1er octobre, en baisse de 2,6&nbsp;% sur le mois et de 5,2&nbsp;% sous son record d’août de 37&nbsp;069,11, mais encore en hausse de 16,6&nbsp;% sur un an.</p>
<h2>La comptabilité mentale rend les pertes obligataires plus difficiles à absorber</h2>
<p>Richard Thaler a décrit ce schéma dans un article de 1999 sur la comptabilité mentale&nbsp;: les gens répartissent leur argent dans des compartiments distincts, chacun avec ses propres règles. La recherche prévoit qu’une baisse dans un compartiment étiqueté sécuritaire est ressentie autrement que la même baisse dans un compartiment étiqueté croissance, parce que le compartiment sécuritaire ne s’est jamais vu attribuer de budget de perte.</p>
<p>La baisse est réelle, et l’occasion l’est tout autant. Mark Malek, chef des placements chez Siebert Financial, a déclaré, selon le Wall Street Journal&nbsp;: «&nbsp;Les détenteurs actuels d’obligations ont subi de douloureuses baisses de prix, mais les nouveaux capitaux peuvent maintenant garantir des rendements introuvables durant une bonne partie des deux dernières décennies.&nbsp;» Les deux moitiés sont vraies en même temps, ce qui rend le moment difficile à lire à partir d’un seul relevé.</p>
<p>Les investisseurs canadiens font face à deux points d’évaluation prévus. Statistique Canada publie l’inflation de septembre le 19 octobre, et la Banque du Canada annonce sa prochaine décision sur le taux, accompagnée d’un nouveau Rapport sur la politique monétaire, le 28 octobre. La Banque a maintenu son taux directeur à 2,25&nbsp;% pour une septième décision consécutive le 2 septembre. Selon le mécanisme de Benartzi et Thaler, chacune de ces dates est un nouveau moment où l’on vérifie son portefeuille et où l’on ressent les pertes.</p>
<h2>La crainte est raisonnable, mais elle vise les mauvais cadrans</h2>
<p>L’anxiété n’est pas irrationnelle. Un sommet de 24 ans du rendement des bons du Trésor à 10 ans est un événement réel, aux conséquences réelles pour le prix des obligations et le coût d’emprunt. Le risque comportemental est que l’attention se porte sur le calendrier, que Wong juge être une piètre base pour chronométrer le marché à court terme, et sur un indice de volatilité qui ne mesure pas les taux.</p>
<p>Rien de cela ne prévoit octobre. Cela décrit où l’attention risque d’être mal dirigée&nbsp;: vers l’histoire frappante d’un krach qui arrive à date fixe et loin de la réévaluation plus lente qui se poursuit du côté des obligations d’État.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients portent deux craintes à la fois. La première est héritée&nbsp;: octobre porte le souvenir de 1929, 1987 et 2008, et ce souvenir est facile à rappeler. L’autre est actuelle&nbsp;: des rendements des obligations d’État à des sommets de 24 ans et un TSX en baisse de 2,6&nbsp;% sur le mois. Les clients qui détiennent des obligations et des placements sensibles aux taux ressentent quelque chose de plus vif que l’anxiété de marché. Un placement qu’ils avaient rangé dans le compartiment sécuritaire affiche une perte, et ils n’avaient jamais prévu de budget pour en subir une là.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Deux choses distinctes se produisent, et je tiens à les garder séparées. D’abord, octobre a la réputation de provoquer des krachs. Au cours des 25 dernières années, le TSX a terminé octobre en hausse 17 fois et le S&amp;P 500, 16 fois. Le mois est souvent agité, mais il n’est généralement pas négatif. Ensuite, et celle-ci est bien réelle, les rendements obligataires ont bondi. Le rendement américain à 10 ans a touché cette semaine son plus haut niveau depuis 2002. Quand les rendements montent, le prix des obligations existantes baisse, et c’est le mécanisme derrière toute baisse de vos obligations. Cela signifie aussi que l’argent neuf peut maintenant rapporter des rendements que nous n’avons pas vus pendant la majeure partie des deux dernières décennies. Nous ne changeons pas le plan à cause du calendrier. Nous surveillons deux dates&nbsp;: l’inflation de septembre le 19 octobre et la décision de la Banque du Canada le 28 octobre. Je vous téléphonerai après chacune.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> retraités qui tirent un revenu de portefeuilles à forte composante obligataire, clients détenant des fonds obligataires à long terme et clients dont l’hypothèque vient à échéance au cours des 12 prochains mois, puisque les rendements des obligations d’État influent sur les taux hypothécaires fixes.</p>
<p><strong>Incidence variable&nbsp;:</strong> clients à portefeuille équilibré dont le volet actions est en légère baisse sur le mois et dont le volet obligataire subit une pression sur les prix.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> clients disposant de liquidités à investir ou dont des CPG et des obligations arrivent bientôt à échéance, et qui peuvent réinvestir à des rendements introuvables durant une bonne partie des deux dernières décennies.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Extraire l’exposition aux titres à revenu fixe de chaque client et signaler les titres à longue durée pour ceux qui tirent un revenu.</div>
<div class="checklist-item">Dresser la liste des clients qui ont communiqué avec le bureau ou consulté leurs comptes cette semaine et noter la question posée par chacun.</div>
<div class="checklist-item">Réserver à l’avance des appels de suivi pour le 19 octobre (inflation de septembre) et le 28 octobre (décision de la Banque du Canada).</div>
<div class="checklist-item">Signaler les clients dont l’hypothèque vient à échéance d’ici 12 mois et confirmer leur plan de renouvellement.</div>
<div class="checklist-item">Consigner chaque conversation et toute instruction reçue d’un client.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Où en est octobre et ce que nous surveillons<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir pris mon appel. Voici un bref résumé de notre discussion.<br><br>
Octobre a la réputation de provoquer des baisses marquées, mais au cours des 25 dernières années, le TSX a terminé le mois en hausse 17 années sur 25. Le mois est souvent volatil sans être négatif.<br><br>
La véritable pression ce mois-ci se situe sur les marchés obligataires. Le rendement américain à 10 ans a touché son plus haut niveau depuis 2002 le 1er octobre, ce qui fait baisser le prix des obligations existantes et augmenter le rendement de l’argent neuf. Votre plan a été conçu en tenant compte de périodes comme celle-ci.<br><br>
Deux dates comptent pour la suite&nbsp;: l’inflation de septembre le 19 octobre et la décision de la Banque du Canada le 28 octobre. Je communiquerai avec vous après chacune. Si votre situation change d’ici là, n’hésitez pas à m’appeler.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes détenant des FNB obligataires ou des CPG&nbsp;:</strong> ils ont encaissé des baisses de prix ce trimestre sans personne à appeler et sans cadre pour décider de conserver ou de réinvestir.</p>
<p><strong>Investisseurs qui détiennent des liquidités&nbsp;:</strong> ils attendent un meilleur point d’entrée alors que les rendements à 10 ans du gouvernement du Canada se situent près de 4&nbsp;%.</p>
<p><strong>Préretraités et retraités dont des CPG ou des obligations arrivent à échéance&nbsp;:</strong> ils font face à des décisions de réinvestissement aux rendements les plus élevés depuis des années.</p>
<p><strong>Propriétaires approchant du renouvellement de leur hypothèque&nbsp;:</strong> ils n’ont pas encore relié le marché obligataire à leur plan financier.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Le rendement des obligations américaines à 10 ans a atteint cette semaine son plus haut niveau en 24 ans, et j’appelle quelques personnes pour savoir si quelqu’un surveille leurs obligations. Avez-vous une minute&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Les chocs de taux ouvrent une fenêtre, car l’investisseur qui gère seul fait face à deux décisions sans cadre&nbsp;: conserver des obligations qui ont perdu de la valeur ou investir ses liquidités aux rendements les plus élevés depuis des années. Octobre ajoute un piège comportemental. Le calendrier dit de craindre un krach, l’indice de volatilité vedette affiche le calme à 16,39, et ce n’est ni l’un ni l’autre qui concentre la pression.</p>
<p>L’asymétrie est claire. L’investisseur autonome voit un mois effrayant et un relevé en baisse. Le conseiller voit une réévaluation des obligations d’État, une occasion à deux volets et deux dates prévues, le 19 et le 28 octobre, pour revoir le plan.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Comment vos obligations ou vos CPG se sont-ils comportés depuis l’été&nbsp;?</p>
<p>2. Quand avez-vous consulté votre compte pour la dernière fois, et qu’avez-vous fait ensuite&nbsp;?</p>
<p>3. Avez-vous une règle pour décider quand vendre, et avec qui la vérifiez-vous&nbsp;?</p>
<p>4. Si la Banque du Canada relevait ses taux le 28 octobre, quelle partie de votre plan en ressentirait d’abord les effets&nbsp;?</p>
<p>5. Si vous saviez que les rendements sont à leur plus haut en des années, que feriez-vous des liquidités que vous détenez aujourd’hui&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Une question sur vos obligations<br><br>
Bonjour [Nom du prospect],<br><br>
Le rendement américain à 10 ans a atteint son plus haut niveau depuis 2002 le 1er octobre, et le rendement canadien à 10 ans est près de son plus haut depuis 2023. Quand les rendements montent, les obligations existantes perdent de la valeur et l’argent neuf rapporte davantage. Les deux sont vrais à la fois, et la bonne réponse dépend de l’investisseur.<br><br>
Je m’entretiens cette semaine avec un petit nombre de personnes sur la façon d’y réfléchir. Auriez-vous 15 minutes le [jour]&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
