});
svg.appendChild(el("text",{x:bandX0+4, y:margin.top+10, "text-anchor":"start", "font-size":"7", "font-weight":"700", fill:"#c0392b", "font-family":FONT}, "5 CLÔTURES > 100\u00a0$"));
if (Math.abs(refVal - closes[n-1])/closes[n-1] >= 0.03){
  svg.appendChild(el("text",{x:margin.left+10, y:refY-10, "text-anchor":"start", "font-size":"7", "font-weight":"700", fill:"#2e7d32", "font-family":FONT}, refVal + "\u00a0$ LE BARIL"));
}
svg.appendChild(el("text",{x:xp(4)+2, y:yp(sma[4])+14, "text-anchor":"start", "font-size":"7.5", fill:"#888888", "font-family":FONT}, "MOY. 5 JOURS"));
events.forEach(function(ev){
  var ex = xp(ev.i);
  var tx = (ev.a === "end") ? ex - 4 : ex + 3;
  var yStart = margin.top + PH - 22;
  ev.l.forEach(function(s, k){
    svg.appendChild(el("text",{x:tx, y:yStart + k*9, "text-anchor":ev.a, "font-size":"7", "font-weight":"700", fill:"#1a3560", "font-family":FONT}, s));
